import{_ as e,o as a,c as r,ae as o}from"./chunks/framework.BajMXG5H.js";const u=JSON.parse('{"title":"Native macOS","description":"","frontmatter":{},"headers":[],"relativePath":"guide/native-macos.md","filePath":"guide/native-macos.md"}'),n={name:"guide/native-macos.md"};function i(s,t,d,l,c,g){return a(),r("div",null,[...t[0]||(t[0]=[o(`<h1 id="native-macos" tabindex="-1">Native macOS <a class="header-anchor" href="#native-macos" aria-label="Permalink to &quot;Native macOS&quot;">​</a></h1><p>Orchestra is built with <a href="https://v2.tauri.app/" target="_blank" rel="noreferrer">Tauri</a>, providing a native macOS experience with minimal resource usage.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hook (curl) → Rust (axum, port 3008) → Store → Tauri Event → React UI</span></span>
<span class="line"><span>                                              → tmux (Command)</span></span>
<span class="line"><span>                                              → Notification</span></span>
<span class="line"><span>                                              → Sound</span></span></code></pre></div><ul><li><strong>Backend</strong>: Rust with axum HTTP server for hook ingestion</li><li><strong>Frontend</strong>: React with Tailwind CSS</li><li><strong>Communication</strong>: Tauri events (no WebSocket needed)</li></ul><h2 id="resource-usage" tabindex="-1">Resource Usage <a class="header-anchor" href="#resource-usage" aria-label="Permalink to &quot;Resource Usage&quot;">​</a></h2><p>Unlike Electron-based alternatives, Tauri apps use the system WebView, resulting in:</p><ul><li><strong>Small binary size</strong> — ~10MB DMG</li><li><strong>Low memory usage</strong> — Typically under 50MB RAM</li><li><strong>Fast startup</strong> — Native Rust backend starts instantly</li></ul><h2 id="system-integration" tabindex="-1">System Integration <a class="header-anchor" href="#system-integration" aria-label="Permalink to &quot;System Integration&quot;">​</a></h2><ul><li><strong>Notifications</strong> — Uses <code>tauri-plugin-notification</code> for native macOS notifications</li><li><strong>Sounds</strong> — Plays system sounds (<code>Glass.aiff</code>) via <code>afplay</code> for audio alerts</li><li><strong>Menu bar</strong> — Standard macOS menu bar with full app settings</li><li><strong>Overlay title bar</strong> — Clean, native-looking title bar design</li></ul><h2 id="app-menu-settings" tabindex="-1">App Menu Settings <a class="header-anchor" href="#app-menu-settings" aria-label="Permalink to &quot;App Menu Settings&quot;">​</a></h2><p>The <strong>Orchestra</strong> menu provides the following toggles:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><strong>Desktop Notifications</strong></td><td>Enable/disable system notifications</td><td>On</td></tr><tr><td><strong>Auto-jump to tmux Session</strong></td><td>Automatically focus the terminal when a cue fires</td><td>Off</td></tr><tr><td><strong>Show Agent Badges</strong></td><td>Show/hide AI agent identifier badges on session cards</td><td>On</td></tr><tr><td><strong>Show Cue Lane</strong></td><td>Show/hide the cue notification bar at the top</td><td>Off</td></tr></tbody></table><h2 id="pomodoro-timer" tabindex="-1">Pomodoro Timer <a class="header-anchor" href="#pomodoro-timer" aria-label="Permalink to &quot;Pomodoro Timer&quot;">​</a></h2><p>Orchestra includes a built-in Pomodoro timer to help you stay focused during coding sessions.</p><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><p>All timer settings are configurable from <strong>Orchestra</strong> menu → <strong>Pomodoro Timer</strong>:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Options</th><th>Default</th></tr></thead><tbody><tr><td><strong>Work Duration</strong></td><td>15, 20, 25, 30, 45, 60 min</td><td>25 min</td></tr><tr><td><strong>Short Break</strong></td><td>3, 5, 10, 15 min</td><td>5 min</td></tr><tr><td><strong>Long Break</strong></td><td>10, 15, 20, 30 min</td><td>15 min</td></tr><tr><td><strong>Cycles before Long Break</strong></td><td>2, 3, 4, 5, 6</td><td>4</td></tr><tr><td><strong>Size</strong></td><td>Small, Medium, Large</td><td>Medium</td></tr><tr><td><strong>Show Reset Button</strong></td><td>Toggle visibility</td><td>On</td></tr><tr><td><strong>Show Skip Button</strong></td><td>Toggle visibility</td><td>On</td></tr></tbody></table><h3 id="cycle-management" tabindex="-1">Cycle Management <a class="header-anchor" href="#cycle-management" aria-label="Permalink to &quot;Cycle Management&quot;">​</a></h3><p>The <strong>Cycle Status</strong> submenu shows your current progress:</p><ul><li><strong>Cycle progress</strong> — e.g., &quot;Cycle: 2/4&quot;</li><li><strong>Current phase</strong> — Working, Short Break, or Long Break</li><li><strong>Reset All Cycles</strong> — Reset cycle progress with a confirmation dialog</li></ul><h3 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h3><ul><li>Click the timer to start/pause</li><li>The timer automatically advances through Work → Short Break → Work → ... → Long Break</li><li>Drag the timer to reposition it anywhere on the dashboard</li><li>A green glow animation plays when a break starts</li></ul><h2 id="technology-stack" tabindex="-1">Technology Stack <a class="header-anchor" href="#technology-stack" aria-label="Permalink to &quot;Technology Stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Technology</th></tr></thead><tbody><tr><td>Backend</td><td>Rust + axum</td></tr><tr><td>Frontend</td><td>React + Tailwind CSS 4</td></tr><tr><td>Desktop</td><td>Tauri v2</td></tr><tr><td>State</td><td><code>Arc&lt;RwLock&lt;Store&gt;&gt;</code></td></tr><tr><td>Notifications</td><td>tauri-plugin-notification</td></tr></tbody></table>`,25)])])}const m=e(n,[["render",i]]);export{u as __pageData,m as default};
